const crypto = require('crypto');
const secret = $env.HARAVAN_WEBHOOK_SECRET || '';
const headerHmac = ($input.item.json.headers['x-haravan-hmacsha256'] || '').trim();
const rawBody = $input.item.binary?.data ? Buffer.from($input.item.binary.data.data, 'base64') : Buffer.from(JSON.stringify($input.item.json.body || {}));
const computed = crypto.createHmac('sha256', secret).update(rawBody).digest('base64');
const verified = secret.length > 0 && headerHmac.length === computed.length && crypto.timingSafeEqual(Buffer.from(computed), Buffer.from(headerHmac));
const order = $input.item.json.body || {};
const isCod = (order.gateway || '').toLowerCase().includes('cod') || (order.financial_status === 'pending');
const totalPrice = Number(order.total_price || 0);
const missingAddress = !(order.shipping_address && order.shipping_address.address1 && order.shipping_address.ward);
const riskFlags = [];
if (isCod && totalPrice >= 3000000) riskFlags.push('HIGH_VALUE_COD');
if (missingAddress) riskFlags.push('INCOMPLETE_VN_ADDRESS');
return { json: { verified, order_id: order.id, order_name: order.name, total_price: totalPrice, is_cod: isCod, risk_flags: riskFlags, needs_cs_call: riskFlags.length > 0 } };
